// Generated by pwa-build.js. Only public build files are stored here.
const CACHE='ift-static-__IFT_VERSION__';
const PRECACHE=__IFT_PRECACHE__;
const STATIC_PATHS=new Set(PRECACHE);
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 try{
  await cache.addAll(PRECACHE.map(path=>new Request(path,{cache:'reload',credentials:'omit'})));
 }catch(error){await caches.delete(CACHE);throw error;}
 await self.skipWaiting();
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 const keys=await caches.keys();
 // Keep the immediately preceding build for tabs that still use its JS chunks.
 const previous=keys.filter(key=>key.startsWith('ift-static-')&&key!==CACHE).slice(-1);
 await Promise.all(keys.filter(key=>key.startsWith('ift-shell-')||key.startsWith('ift-static-')&&key!==CACHE&&!previous.includes(key)).map(key=>caches.delete(key)));
 await self.clients.claim();
})()));
async function cachedPath(path){
 const current=await caches.open(CACHE);
 const found=await current.match(path);if(found)return found;
 for(const key of (await caches.keys()).filter(k=>k.startsWith('ift-static-')&&k!==CACHE).reverse()){
  const response=await (await caches.open(key)).match(path);if(response)return response;
 }
 return null;
}
async function networkPage(request){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
 try{return await fetch(request,{signal:controller.signal});}finally{clearTimeout(timer);}
}
async function shell(request){
 // The shell is build-time HTML only, identical for every user. Account data
 // always comes directly from Supabase after the application has opened.
 const cached=await cachedPath('/');if(cached)return cached;
 try{return await networkPage(request);}catch{
  return new Response('<!doctype html><html lang="en"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IFT - Connection interrupted</title><body style="font:17px/1.6 system-ui;padding:28px;max-width:460px;margin:12vh auto"><h1>Connect to open IFT for the first time</h1><p>The app files are not saved on this device yet. Your account records have not been changed.</p><button onclick="location.reload()">Try again</button> <a href="/recover.html">Repair loading</a></body></html>',{status:503,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});
 }
}
self.addEventListener('fetch',event=>{
 const request=event.request,url=new URL(request.url);
 if(request.method!=='GET'||url.origin!==self.location.origin)return;
 if(request.mode==='navigate'&&(url.pathname==='/'||url.pathname==='/index.html')){
  event.respondWith(shell(request));return;
 }
 // Only exact generated static paths are eligible; never cache APIs, photos,
 // auth callbacks, recovery pages, or arbitrary runtime responses.
 if(url.pathname!=='/'&&url.pathname!=='/index.html'&&(STATIC_PATHS.has(url.pathname)||url.pathname.startsWith('/assets/'))){
  event.respondWith((async()=>await cachedPath(url.pathname)||fetch(request))());
 }
});
